'use strict';

/**
* Symbol used to define a custom string splitting behavior.
*
* @module @stdlib/symbol/split
*
* @example
* var SplitSymbol = require( '@stdlib/symbol/split' );
*
* var str;
* var obj;
* var parts;
*
* function splitHandler() {
*     return [ 'beep', 'boop' ];
* }
*
* if ( SplitSymbol ) {
*     str = 'beep-boop';
*     obj = {};
*     obj[ SplitSymbol ] = splitHandler;
*     parts = str.split( obj );
*     console.log( parts );
*     // => [ 'beep', 'boop' ]
* }
*/

// MAIN //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
